        /* Screen specific shadow (Optional, helps visualize sheets on monitor) */
        @media screen {
            .page {
                box-shadow: 0 0 15px rgba(0,0,0,0.05);
            }
        }

        h1, h2 {
            font-weight: 700;
            color: var(--black);
        }

        p {
            color: var(--gray-700);
            margin-bottom: 16px;
        }

        a {
            color: var(--black);
            text-decoration: underline;
        }

        /* COVER */
