            color: var(--gray-500);
            margin-bottom: 8px;
        }

        .update-title {
            font-size: 24px;
            margin-bottom: 12px;
        }

        .section-label {
            font-size: 11px;
            letter-spacing: 0.1em;
            text-transform: uppercase;
            color: var(--gray-500);
            margin-bottom: 10px;
        }

        .feature-list {
            list-style: none;
            margin-bottom: 20px;
        }

        .feature-list li {
            padding-left: 20px;
            position: relative;
            margin-bottom: 8px;
        }

        .feature-list li::before {
            content: "—";
            position: absolute;
            left: 0;
        }

        .tech-box {
            background: var(--gray-100);
            padding: 16px;
            margin-bottom: 16px;
            font-size: 14px;
        }

        .cta-page {
            text-align: center;
            display: flex;
            flex-direction: column;
            justify-content: center;
        }

        .cta-heading {
            font-size: 36px;
            margin-bottom: 40px;
        }
    </style>
</head>

